@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Company {
  + Name : string
}

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SSN : string
  + PhoneNumber : string
  + Email : string
}

class Customer {
  + Name : string
  + Address : string
  + PhoneNumber : string
  + Email : string
}

class Order {
  + OrderID : int
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Company "1" -- "*" Product
Product "*" -- "1" Country
Product "*" -- "*" Representative
Representative "1" -- "1" Country
Customer "*" -- "*" Country
Representative "1" -- "*" Order
Order "*" -- "1" Product

@enduml

